import sys
import time
import board
import busio
import adafruit_ads1x15
from adafruit_ads1x15 import ADS1115
import picamera2
import paho.mqtt.client as mqtt

# Set up I2C bus
i2c = busio.I2C(board.SCL1, board.SDA1)

# Set up ADS1115 ADC
try:
    ads = adafruit_ads1x15.ADS1115(i2c)
except Exception as e:
    print(f"Failed to initialize ADS1115: {e}")
    sys.exit(1)

# Set up MQTT client
mqtt_client = mqtt.Client()

def readAdc(c):
    """Configure a single-shot conversion for the specified channel with the required configuration bits."""
    try:
        ads.start_conversion(c)
        while not ads.data_ready:
            pass
        return ads.read(c)
    except Exception as e:
        print(f"Failed to read ADC channel {c}: {e}")
        return None

def swap_bytes(data):
    """Swap the bytes of a 16-bit integer to correct for big-endian ordering."""
    return (data >> 8) | (data << 8)

def main():
    try:
        # Set up camera (not used in this example, but included for completeness)
        camera = picamera2.PiCamera()
        camera.close()

        # Main loop
        while True:
            for c in range(4):
                value = readAdc(c)
                if value is not None:
                    print(f"Channel {c}: {swap_bytes(value)}")
            time.sleep(0.05)
    except KeyboardInterrupt:
        # Cleanly exit on KeyboardInterrupt
        print("Exiting...")
    finally:
        # Release resources
        ads.deinit()
        i2c.deinit()
        mqtt_client.disconnect()

if __name__ == "__main__":
    main()

import logging
import sys
import time
import board
import busio
import adafruit_mcp3008
import RPi.GPIO as GPIO
import picamera2
import paho.mqtt.client as mqtt
from gpiozero import Device, OutputDevice
from gpiozero.pins.pigpio import PiGPIOFactory

# Set up logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Set up GPIO
GPIO.setmode(GPIO.BCM)
GPIO.setwarnings(False)
GPIO.cleanup()

# Set up SPI
try:
    spi = busio.SPI(board.SCK, MOSI=board.MOSI, MISO=board.MISO, baudrate=13500000)
except Exception as e:
    logging.error(f"Failed to set up SPI: {e}")
    sys.exit(1)

# Set up MCP3008
try:
    mcp = adafruit_mcp3008.MCP3008(spi, address=0x20)
except Exception as e:
    logging.error(f"Failed to set up MCP3008: {e}")
    sys.exit(1)

# Set up pump relay
try:
    pump = OutputDevice(18, pin_factory=PiGPIOFactory())
except Exception as e:
    logging.error(f"Failed to set up pump relay: {e}")
    sys.exit(1)

class SmartGardenController:
    def __init__(self):
        self.mcp = mcp
        self.pump = pump

    def read_moisture(self):
        try:
            return self.mcp.read_adc(0)
        except Exception as e:
            logging.error(f"Failed to read moisture: {e}")
            return None

    def run_pump(self, seconds):
        try:
            self.pump.on()
            time.sleep(seconds)
            self.pump.off()
        except Exception as e:
            logging.error(f"Failed to run pump: {e}")

    def irrigation_cycle(self):
        moisture = self.read_moisture()
        if moisture is not None and moisture < 450:
            self.run_pump(2)
            return True
        return False

    def close(self):
        self.pump.close()
        GPIO.cleanup()

def schedule_cycles(controller, cycle_count, interval_seconds):
    for _ in range(cycle_count):
        if not controller.irrigation_cycle():
            break
        time.sleep(interval_seconds)

def main():
    try:
        controller = SmartGardenController()
        schedule_cycles(controller, 10, 3)
    except KeyboardInterrupt:
        logging.info("Received keyboard interrupt, exiting")
    finally:
        controller.close()

if __name__ == "__main__":
    main()

