import os
import sys
import signal
import time
import logging
import logging.handlers
import RPi.GPIO as GPIO
import spidev
import board
import busio
import adafruit_ads1x15.ADS1115
from gpiozero import LED, Relay
from gpiozero.pins.pigpio import PiGPIOFactory
from picamera2 import Picamera2
from picamera2.controls import Controls
from paho.mqtt.client import Client as MQTTClient
import dht11

# Set up logging
logger = logging.getLogger(__name__)
logger.setLevel(logging.INFO)
handler = logging.handlers.RotatingFileHandler('greenhouse.log', maxBytes=1000000, backupCount=1)
formatter = logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s')
handler.setFormatter(formatter)
logger.addHandler(handler)

# Set up GPIO
GPIO.setmode(GPIO.BCM)
GPIO.setwarnings(False)
factory = PiGPIOFactory()
GPIO.setwarnings(True)

# Set up SPI
spi = spidev.SpiDev()
spi.open(0, 0)
spi.max_speed_hz = 1000000

# Set up ADC
adc = adafruit_ads1x15.ADS1115.ADS1115(spi, address=0x48)

# Set up DHT22
dht_device = dht11.DHT11(pin=4)

# Set up relays
pump = Relay(17, pin_factory=factory)
fan = Relay(27, pin_factory=factory)
light = Relay(22, pin_factory=factory)

# Set up status LED
status_led = LED(25, pin_factory=factory)

# Set up camera
camera = Picamera2()
camera.configure(Controls.resolution="640x480")

# Set up MQTT
mqtt_client = MQTTClient("greenhouse")
mqtt_client.connect("localhost")

def control_pump(command):
    if command == "on":
        pump.on()
        logger.info("Pump turned on")
    elif command == "off":
        pump.off()
        logger.info("Pump turned off")
    else:
        logger.error("Invalid pump command")

def control_fan(command):
    if command == "on":
        fan.on()
        logger.info("Fan turned on")
    elif command == "off":
        fan.off()
        logger.info("Fan turned off")
    else:
        logger.error("Invalid fan command")

def control_light(command):
    if command == "on":
        light.on()
        logger.info("Light turned on")
    elif command == "off":
        light.off()
        logger.info("Light turned off")
    else:
        logger.error("Invalid light command")

def set_led_status(status):
    if status == "online":
        status_led.on()
        logger.info("Status LED set to online")
    elif status == "offline":
        status_led.off()
        logger.info("Status LED set to offline")
    elif status == "error":
        status_led.blink(5, 0.2)
        logger.info("Status LED set to error")
    elif status == "synchronizing":
        status_led.blink(5, 0.2)
        logger.info("Status LED set to synchronizing")
    else:
        logger.error("Invalid status")

def read_dht22():
    try:
        humidity, temperature = dht_device.read()
        return humidity, temperature
    except Exception as e:
        logger.warning("Failed to read DHT22 sensor")
        return None, None

def read_adc():
    try:
        return adc.read_adc(0, gain=1)
    except Exception as e:
        logger.warning("Failed to read ADC")
        return None

def read_camera():
    try:
        camera.capture("image.jpg")
        return True
    except Exception as e:
        logger.warning("Failed to capture image")
        return False

def process_command(command):
    if command == "pump_on":
        control_pump("on")
    elif command == "pump_off":
        control_pump("off")
    elif command == "fan_on":
        control_fan("on")
    elif command == "fan_off":
        control_fan("off")
    elif command == "light_on":
        control_light("on")
    elif command == "light_off":
        control_light("off")
    else:
        logger.error("Invalid command")

def watchdog():
    start_time = time.time()
    while True:
        try:
            humidity, temperature = read_dht22()
            if humidity is not None and temperature is not None:
                logger.info(f"Temperature: {temperature}°C, Humidity: {humidity}%")
                mqtt_client.publish("temperature", str(temperature))
                mqtt_client.publish("humidity", str(humidity))
                start_time = time.time()
            else:
                logger.warning("No DHT22 data")
            try:
                adc_value = read_adc()
                if adc_value is not None:
                    logger.info(f"ADC value: {adc_value}")
                    mqtt_client.publish("adc", str(adc_value))
                    start_time = time.time()
                else:
                    logger.warning("No ADC data")
            except Exception as e:
                logger.warning("Failed to read ADC")
            try:
                if read_camera():
                    logger.info("Image captured")
                    mqtt_client.publish("image", "image.jpg")
                    start_time = time.time()
                else:
                    logger.warning("Failed to capture image")
            except Exception as e:
                logger.warning("Failed to capture image")
            try:
                process_command(mqtt_client.polling_commands())
                start_time = time.time()
            except Exception as e:
                logger.warning("Failed to process command")
            time.sleep(300)
        except Exception as e:
            logger.error(f"Watchdog error: {e}")
            os.execv(sys.executable, [sys.executable] + sys.argv)
        if time.time() - start_time > 600:
            logger.error("Watchdog timeout")
            os.execv(sys.executable, [sys.executable] + sys.argv)

def signal_handler(sig, frame):
    logger.info("Received signal, cleaning up")
    GPIO.cleanup()
    spi.close()
    mqtt_client.disconnect()
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def main():
    try:
        set_led_status("online")
        watchdog()
    except Exception as e:
        logger.error(f"Main error: {e}")
        GPIO.cleanup()
        spi.close()
        mqtt_client.disconnect()

if __name__ == "__main__":
    main()

import argparse
import logging
import queue
import time
import threading
import sys
import signal
import gpiozero
from gpiozero import DigitalInputDevice
from picamera2 import Picamera2
from picamera2 import Pi2Camera
from adafruit_mcp3008 import MCP3008
import board
import spidev
import paho.mqtt.client as mqtt

class SoundSensor:
    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins, channels, spi_speed=1000000, log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.stopped = False

        if self.sensor_type == 'digital':
            self.sensor = [DigitalInputDevice(pin, pull_up=1) for pin in gpio_pins]
        elif self.sensor_type == 'analog':
            self.spi = spidev.SpiDev()
            self.spi.open(0, 0)
            self.spi.max_speed_hz = self.spi_speed
            self.mcp3008 = MCP3008(self.spi, device=0)
        else:
            raise ValueError('Invalid sensor type')

    def read(self):
        if self.sensor_type == 'digital':
            return [sensor.value for sensor in self.sensor]
        elif self.sensor_type == 'analog':
            return [self.mcp3008.read(channel) for channel in self.channels]

    def detect_event(self):
        while not self.stopped:
            reading = self.read()
            if self.sensor_type == 'digital':
                for i, value in enumerate(reading):
                    if value and reading.count(1) > 1:
                        self.log_event(f'Digital sensor {self.sensor_id} detected event')
            elif self.sensor_type == 'analog':
                for i, value in enumerate(reading):
                    if value >= self.threshold:
                        self.log_event(f'Analog sensor {self.sensor_id} detected event')
            time.sleep(1 / self.sample_rate)

    def log_event(self, message):
        if self.log_queue:
            self.log_queue.put(message)

    def run(self):
        self.detect_event()

    def stop(self):
        self.stopped = True

def main():
    parser = argparse.ArgumentParser(description='Sound sensor monitoring')
    parser.add_argument('--sensor_type', type=str, default='digital', choices=['digital', 'analog'])
    parser.add_argument('--threshold', type=int, default=0)
    parser.add_argument('--sample_rate', type=int, default=1)
    parser.add_argument('--log_file', type=str, default='log.txt')
    parser.add_argument('--gpio_pins', type=int, nargs='+', default=[17])
    parser.add_argument('--channels', type=int, nargs='+', default=[0])
    parser.add_argument('--spi_speed', type=int, default=1000000)
    parser.add_argument('--sensor_ids', type=str, nargs='+', default=['sensor1'])
    args = parser.parse_args()

    logging.basicConfig(filename=args.log_file, level=logging.INFO, format='%(asctime)s - %(message)s')

    log_queue = queue.Queue()

    sensors = []
    for sensor_id, sensor_type in zip(args.sensor_ids, [args.sensor_type] * len(args.sensor_ids)):
        sensor = SoundSensor(sensor_id, sensor_type, args.threshold, args.sample_rate, args.gpio_pins, args.channels, args.spi_speed, log_queue)
        sensors.append(sensor)

    def signal_handler(sig, frame):
        for sensor in sensors:
            sensor.stop()
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)

    threads = []
    for sensor in sensors:
        thread = threading.Thread(target=sensor.run)
        thread.start()
        threads.append(thread)

    try:
        for thread in threads:
            thread.join()
    except KeyboardInterrupt:
        for sensor in sensors:
            sensor.stop()
        for thread in threads:
            thread.join()

    for sensor in sensors:
        if sensor.sensor_type == 'digital':
            for pin in sensor.gpio_pins:
                gpiozero.Device.unexport(pin)
        elif sensor.sensor_type == 'analog':
            sensor.spi.close()

if __name__ == '__main__':
    main()

