import sys
import signal
import time
import board
import busio
from adafruit_mcp3008 import MCP3008
import picamera2
import paho.mqtt.client as mqtt
import gpiozero
from gpiozero import LED

class MQ2Sensor:
    def __init__(self, spi_bus, chip_select):
        self.spi_bus = busio.SPI(board.SCK, MOSI=board.MOSI, MISO=board.MISO)
        self.mcp3008 = MCP3008(spi_bus, chip_select=chip_select)
        self.channel = 0

    def read_raw(self):
        try:
            return self.mcp3008.read(self.channel)
        except OSError as e:
            print(f"SPI bus error: {e}")
            return None

class MQ2:
    def __init__(self, sensor):
        self.sensor = sensor

    def read_ppm(self):
        raw = self.sensor.read_raw()
        if raw is None:
            return None
        return (raw * 1000) / 1023

class AlertSystem:
    def __init__(self, ppm):
        self.ppm = ppm

    def get_alert_level(self):
        if self.ppm < 150:
            return "safe"
        elif self.ppm < 400:
            return "warning"
        else:
            return "danger"

def signal_handler(sig, frame):
    print("Exiting...")
    try:
        spi_device.close()
    except NameError:
        pass
    sys.exit(0)

def main():
    global spi_device
    spi_device = None

    # Set up SPI device
    try:
        spi_device = busio.SPI(board.SCK, MOSI=board.MOSI, MISO=board.MISO)
    except OSError as e:
        print(f"SPI bus error: {e}")
        return

    # Set up MQ-2 sensor
    sensor = MQ2Sensor(spi_device, 0)
    mq2 = MQ2(sensor)

    # Set up camera
    camera = picamera2.Picamera2()

    # Set up MQTT client
    client = mqtt.Client()
    client.connect("localhost")

    # Set up LED
    led = LED(17)

    # Set up signal handler
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Sample sensor 12 times at 0.5-second intervals
    for _ in range(12):
        ppm = mq2.read_ppm()
        if ppm is None:
            print("Failed to read ppm")
            continue
        alert_level = AlertSystem(ppm).get_alert_level()
        print(f"PPM: {ppm}, Alert level: {alert_level}")
        client.publish("sensor/mq2/ppm", ppm)
        client.publish("sensor/mq2/alert", alert_level)
        if alert_level == "danger":
            led.on()
        else:
            led.off()
        time.sleep(0.5)

    # Release resources
    try:
        spi_device.close()
    except NameError:
        pass
    try:
        camera.close()
    except NameError:
        pass
    client.disconnect()

if __name__ == "__main__":
    main()

