            return None
        return (raw * 1000) / 1023

class AlertSystem:
    def __init__(self, ppm):
        self.ppm = ppm

    def get_alert_level(self):
        if self.ppm < 150:
            return "safe"
        elif self.ppm < 400:
            return "warning"
        else:
            return "danger"

def signal_handler(sig, frame):
    print("Exiting...")
    try:
        spi_device.close()
    except NameError:
        pass
    sys.exit(0)

def main():
    global spi_device
    spi_device = None

    # Set up SPI device
    try:
        spi_device = busio.SPI(board.SCK, MOSI=board.MOSI, MISO=board.MISO)
    except OSError as e:
        print(f"SPI bus error: {e}")
        return

    # Set up MQ-2 sensor
    sensor = MQ2Sensor(spi_device, 0)
    mq2 = MQ2(sensor)

    # Set up camera
    camera = picamera2.Picamera2()

    # Set up MQTT client
    client = mqtt.Client()
    client.connect("localhost")

    # Set up LED
    led = LED(17)

    # Set up signal handler
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Sample sensor 12 times at 0.5-second intervals
    for _ in range(12):
        ppm = mq2.read_ppm()
        if ppm is None:
            print("Failed to read ppm")
            continue
        alert_level = AlertSystem(ppm).get_alert_level()
        print(f"PPM: {ppm}, Alert level: {alert_level}")
        client.publish("sensor/mq2/ppm", ppm)
        client.publish("sensor/mq2/alert", alert_level)
        if alert_level == "danger":
            led.on()
        else:
            led.off()
        time.sleep(0.5)

    # Release resources
    try:
        spi_device.close()
    except NameError:
        pass
    try:
        camera.close()
    except NameError:
        pass
    client.disconnect()

if __name__ == "__main__":
    main()
```

This code defines a class-based interface for the MQ-2 sensor, which reads the raw 10-bit value from the sensor and converts it to an estimated ppm concentration. It also defines an `AlertSystem` class to determine the alert level based on the ppm concentration. The main function sets up the SPI device, MQ-2 sensor, camera, and MQTT client, samples the sensor 12 times at 0.5-second intervals, and releases resources on exit. The code handles SPI bus errors and ensures that all resources are released on every exit path, including proper handling of SIGINT and SIGTERM signals.

