class BalanceBeamController:
    def __init__(self):
        self.servo = Servo(pin=25, min_pulse_width=0.5, max_pulse_width=2.5, active_high=False, pin_factory=PiGPIOFactory())
        self.sensor = HCSR04(trigger_pin=23, echo_pin=24)
        self.max_error = 25
        self.tolerance = 3
        self.setpoint = 25
        self.consecutive_tolerance = 0
        self.mqtt_client = None

    def read_distance(self):
        try:
            return self.sensor.distance * 100
        except Exception as e:
            logging.error(f"Failed to read distance: {e}")
            return None

    def update_pid(self, distance):
        if abs(distance - self.setpoint) > self.max_error:
            logging.warning(f"Absolute error exceeds maximum error: {abs(distance - self.setpoint)} cm")
            return None
        error = self.setpoint - distance
        if abs(error) <= self.tolerance:
            self.consecutive_tolerance += 1
            if self.consecutive_tolerance >= 3:
                self.consecutive_tolerance = 0
                self.servo.detach()
                return None
        else:
            self.consecutive_tolerance = 0
        return error

    def control_servo(self, error):
        if error is not None:
            angle = int((error / self.max_error) * 50)
            try:
                self.servo.value = angle / 50
            except Exception as e:
                logging.error(f"Failed to set servo: {e}")

    def run(self):
        try:
            self.mqtt_client = mqtt.Client()
            self.mqtt_client.connect("localhost")
            self.mqtt_client.loop_start()
        except Exception as e:
            logging.error(f"Failed to connect to MQTT broker: {e}")
            return

        while True:
            distance = self.read_distance()
            if distance is None:
                time.sleep(0.1)
                continue
            logging.info(f"Distance: {distance} cm")
            error = self.update_pid(distance)
            if error is None:
                continue
            self.control_servo(error)
            self.mqtt_client.publish("balance_beam", str(error))
            time.sleep(0.1)

    def cleanup(self):
        try:
            self.mqtt_client.loop_stop()
            self.mqtt_client.disconnect()
        except Exception as e:
            logging.error(f"Failed to disconnect from MQTT broker: {e}")
        try:
            self.servo.detach()
        except Exception as e:
            logging.error(f"Failed to detach servo: {e}")
        try:
            self.sensor.deinit()
        except Exception as e:
            logging.error(f"Failed to deinit sensor: {e}")

def signal_handler(sig, frame):
    controller.cleanup()
    sys.exit(0)

if __name__ == "__main__":
    controller = BalanceBeamController()
    signal.signal(signal.SIGINT, signal_handler)
    controller.run()

