import argparse
import csv
import datetime
import logging
import os
import signal
import sys
import time
from gpiozero import Button
from picamera2 import Picamera2
from picamera2 import V4L2
from paho.mqtt.client import Client
import RPi.GPIO as GPIO

# Set up logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s %(levelname)s: %(message)s')

def setup_gpio(pins):
    GPIO.setmode(GPIO.BCM)
    for pin in pins:
        GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        try:
            GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
            logging.info(f"GPIO {pin} setup successful")
        except Exception as e:
            logging.error(f"Failed to setup GPIO {pin}: {e}")
            sys.exit(1)

def calibrate_sensors(pins, interval, duration):
    logging.info("Calibrating sensors...")
    thresholds = {}
    for pin in pins:
        high_count = 0
        for _ in range(int(duration / interval)):
            time.sleep(interval)
            if GPIO.input(pin):
                high_count += 1
        threshold = (high_count / (duration / interval)) * 100 + 20
        thresholds[pin] = threshold
        logging.info(f"Calibration for GPIO {pin}: {threshold}%")
    return thresholds

def main():
    parser = argparse.ArgumentParser(description="Monitor vibration sensors and capture images")
    parser.add_argument("-g", "--gpio", type=int, nargs="+", required=True, help="GPIO pins to monitor")
    parser.add_argument("-l", "--log_file", type=str, required=True, help="CSV log file")
    parser.add_argument("-i", "--interval", type=float, required=True, help="Sensor sampling interval")
    parser.add_argument("-c", "--calibrate", type=int, required=True, help="Calibration duration")
    parser.add_argument("-p", "--picture_interval", type=int, required=True, help="Picture interval")
    args = parser.parse_args()

    try:
        setup_gpio(args.gpio)
    except Exception as e:
        logging.error(f"Failed to setup GPIO: {e}")
        sys.exit(1)

    try:
        with open(args.log_file, "w", newline="") as csvfile:
            writer = csv.writer(csvfile)
            writer.writerow(["timestamp", "sensor1", "sensor2", "sensor3"])
    except Exception as e:
        logging.error(f"Failed to open log file: {e}")

    try:
        camera = Picamera2()
        camera.configure(main={"mode": V4L2.PREVIEW_MODE.SENSOR_OV5647})
        camera.start_preview()
    except Exception as e:
        logging.warning(f"Failed to initialize camera: {e}")
        camera = None

    try:
        thresholds = calibrate_sensors(args.gpio, args.interval, args.calibrate)
    except Exception as e:
        logging.error(f"Failed to calibrate sensors: {e}")
        sys.exit(1)

    try:
        while True:
            for pin in args.gpio:
                time.sleep(args.interval)
                high_count = 0
                for _ in range(10):
                    if GPIO.input(pin):
                        high_count += 1
                high_percentage = (high_count / 10) * 100
                if high_percentage > thresholds[pin]:
                    state = 1
                else:
                    state = 0
                with open(args.log_file, "a", newline="") as csvfile:
                    writer = csv.writer(csvfile)
                    writer.writerow([datetime.datetime.now().isoformat(timespec="milliseconds") + "Z", state, state, state])
                csvfile.flush()
            if camera:
                try:
                    camera.capture("images/" + datetime.datetime.now().isoformat(timespec="milliseconds") + ".jpg")
                except Exception as e:
                    logging.warning(f"Failed to capture image: {e}")
            time.sleep(args.picture_interval)
    except KeyboardInterrupt:
        logging.info("Shutting down...")
        GPIO.cleanup()
        if camera:
            camera.close()
        sys.exit(0)

if __name__ == "__main__":
    main()

