import logging
import time
import board
import busio
from adafruit_bus_device.i2c_device import I2CDevice
import adafruit_dht
import picamera2
import paho.mqtt.client as mqtt
import crccheck.crc as crc
import gpiozero

# Set up logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class DHT20:
    def __init__(self, i2c_bus=1):
        self.i2c_bus = i2c_bus
        self.i2c_device = None
        self.power_up()

    def power_up(self):
        try:
            self.i2c_device = I2CDevice(board.I2C(self.i2c_bus), 0x5c)
            time.sleep(0.5)  # Wait for power stabilization
            status = self.read_status()
            if status & 0x80 != 0x80:
                logger.error("DHT20 status register mismatch")
                return False
        except OSError as e:
            logger.error(f"I2C bus error: {e}")
            return False

    def read_status(self):
        try:
            return self.i2c_device.read(1)[0]
        except OSError as e:
            logger.error(f"I2C bus error: {e}")
            return None

    def read_data(self):
        try:
            data = self.i2c_device.read(7)
            humidity = (data[1] << 11) | (data[2] << 1) | (data[3] >> 7)
            temperature = (data[3] << 11) | (data[4] << 1) | (data[5] >> 7)
            crc = data[6]
            crc_calculated = crc.crc8(data[:6], crc.crc8poly=0x31, crc8init=0x00)
            if crc_calculated != crc:
                logger.warning("CRC error")
                return None, None, True
            return temperature / 10, humidity / 10, False
        except OSError as e:
            logger.error(f"I2C bus error: {e}")
            return None, None, True

    def poll(self):
        for attempt in range(6):
            try:
                data = self.read_data()
                if data is not None:
                    return data
            except OSError as e:
                logger.warning(f"I2C bus error: {e}")
            time.sleep(2)
        return None, None, True

    def cleanup(self):
        if self.i2c_device is not None:
            self.i2c_device = None

    def __del__(self):
        self.cleanup()

    def get_data(self):
        while True:
            data = self.poll()
            if data is not None:
                return data
            time.sleep(0.1)
            if attempt >= 5:
                return None, None, True

# Example usage
dht20 = DHT20()
data = dht20.get_data()
if data is not None:
    temperature, humidity, crc_error = data
    logger.info(f"Temperature: {temperature}°C, Humidity: {humidity}%")
