class RotaryEncoder:
    def __init__(self, clk_pin, dt_pin, callback=None, debounce_time=0.005):
        self.clk_pin = gpiozero.Button(clk_pin, pull_up=True, bounce_time=debounce_time)
        self.dt_pin = gpiozero.Button(dt_pin, pull_up=True, bounce_time=debounce_time)
        self.callback = callback
        self.prev_clk_state = None
        self.prev_dt_state = None
        self.counter = 0
        self.lock = threading.Lock()

        self.clk_pin.when_pressed = self._on_clk_edge
        self.dt_pin.when_pressed = self._on_dt_edge

    def _on_clk_edge(self):
        with self.lock:
            if self.prev_clk_state is not None:
                if self.prev_clk_state != self.clk_pin.value:
                    self._handle_rotation()

    def _on_dt_edge(self):
        with self.lock:
            if self.prev_dt_state is not None:
                if self.prev_dt_state != self.dt_pin.value:
                    self._handle_rotation()

    def _handle_rotation(self):
        with self.lock:
            if self.prev_clk_state is not None:
                if self.prev_dt_state is not None:
                    if self.prev_dt_state != self.clk_pin.value:
                        self.counter += 1
                    else:
                        self.counter -= 1
                    if self.callback is not None:
                        try:
