import sys
import signal
import time
import board
import digitalio
import adafruit_rainbowhat
import adafruit_tlc59711
import picamera2
import picamera2.controls
import paho.mqtt.client as mqtt
import gpiozero
from gpiozero import LED, Buzzer
from gpiozero.pins.pigpio import PiGPIOFactory
from gpiozero.tools import active_high
from gpiozero.pins.rpi import RPiPin
from gpiozero.pins.pigpio import PiGPIOFactory

# Set up GPIO factory for pigpio
gpiozero.pins.factory = PiGPIOFactory()

# Set up signal handlers
def signal_handler(sig, frame):
    print('Exiting...')
    try:
        display.off()
    except Exception as e:
        print(f"Error turning off display: {e}", file=sys.stderr)
    try:
        rainbowhat.leds.off()
    except Exception as e:
        print(f"Error turning off Rainbow HAT LEDs: {e}", file=sys.stderr)
    try:
        apa102.off()
    except Exception as e:
        print(f"Error turning off APA102 strip: {e}", file=sys.stderr)
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Set up Rainbow HAT
try:
    rainbowhat = adafruit_rainbowhat.RainbowHat()
except Exception as e:
    print(f"Error initializing Rainbow HAT: {e}", file=sys.stderr)
    rainbowhat = None

# Set up APA102 strip
try:
    apa102 = adafruit_tlc59711.TLC59711(board.TEARDROP)
    apa102.fill((0, 0, 0))
except Exception as e:
    print(f"Error initializing APA102 strip: {e}", file=sys.stderr)
    apa102 = None

# Set up display
try:
    display = adafruit_rainbowhat.Display()
except Exception as e:
    print(f"Error initializing display: {e}", file=sys.stderr)
    display = None

# Set up LEDs
try:
    green_led = LED(board.GREEN_LED)
    blue_led = LED(board.BLUE_LED)
except Exception as e:
    print(f"Error initializing LEDs: {e}", file=sys.stderr)
    green_led = None
    blue_led = None

# Set up buzzer
try:
    buzzer = Buzzer(board.BUZZER)
except Exception as e:
    print(f"Error initializing buzzer: {e}", file=sys.stderr)
    buzzer = None

# Set up capacitive touchpads
try:
    touch_a = gpiozero.TouchPad(board.GPIO5, pull_up=True)
    touch_b = gpiozero.TouchPad(board.GPIO6, pull_up=True)
    touch_c = gpiozero.TouchPad(board.GPIO12, pull_up=True)
except Exception as e:
    print(f"Error initializing touchpads: {e}", file=sys.stderr)
    touch_a = None
    touch_b = None
    touch_c = None

# Set up MQTT client
try:
    client = mqtt.Client()
    client.connect("localhost")
except Exception as e:
    print(f"Error initializing MQTT client: {e}", file=sys.stderr)
    client = None

# Set up bit states
bit_states = [False, False, False]

# Main loop
while True:
    try:
        # Wait for touch events
        if touch_a.value:
            bit_states[2] = not bit_states[2]
        if touch_b.value:
            bit_states[1] = not bit_states[1]
        if touch_c.value:
            bit_states[0] = not bit_states[0]

        # Update LEDs
        try:
            rainbowhat.leds[0] = bit_states[2]
            rainbowhat.leds[1] = bit_states[1]
            rainbowhat.leds[2] = bit_states[0]
        except Exception as e:
            print(f"Error updating Rainbow HAT LEDs: {e}", file=sys.stderr)

        # Update display
        try:
            display.text(f"{int(''.join('01' if bit else '0' for bit in bit_states), 2)}", 0, 0, color=0x00FF00)
        except Exception as e:
            print(f"Error updating display: {e}", file=sys.stderr)

        # Update APA102 strip
        try:
