class BlinkLED:
    def __init__(self, pin):
        self.pin = pin
        self.led = gpiozero.LED(pin)

    def blink(self, times):
        for _ in range(times):
            self.led.on()
            time.sleep(1)
            self.led.off()
            time.sleep(1)

    def cleanup(self):
        self.led.off()

