class SG90Servo:
    def __init__(self, pin):
        try:
            gpiozero.Device.pin_factory = PiGPIOFactory()
            self.servo = ServoKit(channels=16, initial_pulse_width=0.5, min_pulse_width=0.05, max_pulse_width=2.5, frequency=50)
            self.servo.servo[0].attach(pin)
        except Exception as e:
            logging.error(f"Failed to initialize servo: {e}")
            sys.exit(1)

    def _angle_to_duty_cycle(self, angle):
        return (angle / 180) * 2.5 + 0.05

    def move_to(self, angle):
        try:
            self.servo.servo[0].angle = angle
        except Exception as e:
            logging.error(f"Failed to move servo to angle {angle}: {e}")

    def stop(self):
        try:
            self.servo.servo[0].off()
        except Exception as e:
            logging.error(f"Failed to stop servo: {e}")

def sweep_servo(servo, angles):
    for angle in angles:
