from adafruit_circuitpython_mqtt import MQTT
from paho.mqtt.client import Client as MQTTClient
import pytest
import mock
import unittest.mock

# Set up logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# Define the Modbus RTU servo motor controller class
class ModbusServoController:
    def __init__(self, port, baudrate=115200, timeout=1):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial = None
        self.mqtt_client = None

    def _connect_serial(self):
        try:
            self.serial = serial.Serial(self.port, self.baudrate, timeout=self.timeout)
        except serial.SerialException as e:
            logger.warning(f"Failed to connect to serial port {self.port}: {e}")
            return False
        return True

    def _disconnect_serial(self):
        if self.serial:
            self.serial.close()
            self.serial = None

    def _send_command(self, function_code, address, value=None):
        if not self.serial:
            logger.warning("Serial port not connected")
            return False

        # Send the command
        try:
            self.serial.write(b'\x02' + bytes([function_code]) + bytes([address >> 8]) + bytes([address & 0xFF]) + bytes([len(value) if value else 0]) + (bytes([value]) if value else b''))
            self.serial.write(b'\x03')
        except serial.SerialException as e:
            logger.warning(f"Failed to send command: {e}")
            return False

        # Wait for the response
        try:
            response = self.serial.read(9)
        except serial.SerialException as e:
            logger.warning(f"Failed to read response: {e}")
            return False

        # Check the CRC
        if response[8] != (response[0] + response[1] + response[2] + response[3] + response[4] + response[5] + response[6] + response[7]) % 256:
            logger.warning("CRC error")
            return False

        # Check the function code
        if response[0] != function_code:
            logger.warning("Invalid function code")
            return False

        # Check the byte count
        if response[1] != len(value) if value else 0:
            logger.warning("Invalid byte count")
            return False

        # Return the value
        return response[2:]

    def read_holding_registers(self, address, count):
        if not self.serial:
            logger.warning("Serial port not connected")
            return None

        return self._send_command(3, address, None)

    def write_single_holding_register(self, address, value):
        if not self.serial:
            logger.warning("Serial port not connected")
            return False

        return self._send_command(6, address, value)

    def write_multiple_holding_registers(self, address, values):
        if not self.serial:
            logger.warning("Serial port not connected")
            return False

        return self._send_command(16, address, values)

    def connect_mqtt(self, host, port, username, password):
        self.mqtt_client = MQTTClient(client_id="modbus_servo_controller", clean_session=True, userdata=None, protocol=MQTTv5, transport="tcp")
        self.mqtt_client.on_connect = self._on_mqtt_connect
        self.mqtt_client.on_disconnect = self._on_mqtt_disconnect
        self.mqtt_client.on_message = self._on_mqtt_message
        self.mqtt_client.username_pw_set(username, password)
        self.mqtt_client.connect(host, port)

    def _on_mqtt_connect(self, client, userdata, flags, rc):
        logger.info(f"Connected to MQTT broker with result code {rc}")

    def _on_mqtt_disconnect(self, client, userdata, rc):
        logger.info(f"Disconnected from MQTT broker with result code {rc}")

    def _on_mqtt_message(self, client, userdata, message):
        logger.info(f"Received MQTT message: {message.topic} {message.payload}")

    def publish_mqtt(self, topic, message):
        if not self.mqtt_client:
            logger.warning("MQTT client not connected")
            return False

        self.mqtt_client.publish(topic, message)
        return True

    def disconnect_mqtt(self):
        if self.mqtt_client:
            self.mqtt_client.disconnect()
            self.mqtt_client = None

    def cleanup(self):
        self._disconnect_serial()
        self.disconnect_mqtt()

def signal_handler(sig, frame):
    logger.info("Exiting...")
    controller.cleanup()
    sys.exit(0)

