    "servo_speed": {"R/W": "W", "Register": 0x0001, "functioncode": 6},
    "servo_acceleration": {"R/W": "W", "Register": 0x0002, "functioncode": 16},
}

# Define the servo motor controller
controller = ModbusServoController("/dev/serial0")

# Connect to the serial port
if not controller._connect_serial():
    sys.exit(1)

# Connect to the MQTT broker
controller.connect_mqtt("localhost", 1883, "username", "password")

# Define the test cases
class TestModbusServoController(unittest.TestCase):
    def test_read_holding_registers(self):
        response = controller.read_holding_registers(0x0000, 1)
        self.assertIsNotNone(response)

    def test_write_single_holding_register(self):
        result = controller.write_single_holding_register(0x0001, 0x01)
        self.assertTrue(result)

    def test_write_multiple_holding_registers(self):
        result = controller.write_multiple_holding_registers(0x0002, [0x01, 0x02, 0x03])
        self.assertTrue(result)

    def test_publish_mqtt(self):
        result = controller.publish_mqtt("test/topic", "Hello, world!")
        self.assertTrue(result)

if __name__ == "__main__":
