# Define the PCA9685 address and the I2C bus
PCA9685_ADDRESS = 0x40
I2C_BUS = 1

# Define the ServoKit
def create_servo_kit():
    try:
        pca = adafruit_pca9685.PCA9685(I2C_BUS, address=PCA9685_ADDRESS)
        pca.frequency = 60
        return ServoKit(channels=16, i2c=pca)
    except OSError as e:
        logging.error(f"Failed to initialize PCA9685: {e}")
        sys.exit(1)

# Define the MQTT client
def create_mqtt_client():
    try:
        client = mqtt.Client()
        client.connect("localhost")
        return client
    except ConnectionRefusedError as e:
        logging.error(f"Failed to connect to MQTT broker: {e}")
        sys.exit(1)

# Define the grab_object function
def grab_object(kit, channel):
    if not (0 <= channel <= 15):
        raise ValueError("Channel number must be between 0 and 15")
    try:
        kit.servo[0].angle = 90
    except ValueError as e:
        logging.error(f"Failed to set servo angle: {e}")

# Define the release_object function
def release_object(kit, channel):
    if not (0 <= channel <= 15):
        raise ValueError("Channel number must be between 0 and 15")
    try:
        kit.servo[0].angle = 150
    except ValueError as e:
        logging.error(f"Failed to set servo angle: {e}")

# Define the move_servo function
def move_servo(kit, channel, target_angle):
