from dataclasses import dataclass
from paho.mqtt.client import Client as MQTTClient
from enum import Enum

# Set up logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Define the GPSReadings dataclass
@dataclass
class GPSReadings:
    latitude: float
    longitude: float
    altitude: float
    satellite_count: int

# Define the GPSReader class
class GPSReader:
    def __init__(self, port, baudrate=9600, timeout=1):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.gps = None
        self.mqtt_client = None

    def connect(self):
        try:
            self.gps = UARTGPS(self.port, baudrate=self.baudrate, timeout=self.timeout)
            self.gps.send_command(b'PMTK314,0,0,0,0,0,0,0,0,0*77')
            self.mqtt_client = MQTTClient("GPSReader", "localhost")
            self.mqtt_client.connect()
            logging.info("Connected to GPS and MQTT")
        except serial.SerialException as e:
            logging.error(f"Failed to open GPS port: {e}")

    def disconnect(self):
        if self.gps:
            self.gps.deinit()
        if self.mqtt_client:
            self.mqtt_client.disconnect()

    def read(self):
        if not self.gps:
            return None
        try:
            sentence = self.gps.read()
            if sentence:
                # Parse GPGGA sentence
                parts = sentence.decode().split(',')
                if len(parts) < 13 or parts[0] != '$GPGGA':
                    logging.warning(f"Invalid GPGGA sentence: {sentence}")
                    return None
                try:
                    latitude = self.parse_latitude(parts[2], parts[3])
                    longitude = self.parse_longitude(parts[4], parts[5])
                    altitude = float(parts[9])
                    satellite_count = int(parts[7])
                    return GPSReadings(latitude, longitude, altitude, satellite_count)
                except ValueError as e:
                    logging.error(f"Error parsing GPGGA sentence: {e}")
                    return None
        except serial.SerialTimeoutException:
            logging.warning("Timeout reading from GPS")
        return None

    def parse_latitude(self, degrees, minutes):
        sign = 1 if degrees[0] == 'N' else -1
        return sign * (float(degrees[1:]) + float(minutes) / 60)

    def parse_longitude(self, degrees, minutes):
        sign = 1 if degrees[0] == 'E' else -1
        return sign * (float(degrees[1:]) + float(minutes) / 60)

def signal_handler(sig, frame):
    logging.info("Exiting")
    gps_reader.disconnect()
    sys.exit(0)

def main():
    gps_reader = GPSReader('/dev/serial0')
    gps_reader.connect()
    try:
        while True:
            reading = gps_reader.read()
            if reading:
                logging.info(f"Latitude: {reading.latitude}, Longitude: {reading.longitude}, Altitude: {reading.altitude}, Satellite Count: {reading.satellite_count}")
                gps_reader.mqtt_client.publish('gps/reading', str(reading))
            time.sleep(1)
    except KeyboardInterrupt:
        logging.info("Interrupted")
    except Exception as e:
        logging.error(f"Error: {e}")
    finally:
        gps_reader.disconnect()

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    main()

