import sys
import signal
import time
import logging
from gpiozero import UART
from picamera2 import Picamera2
from adafruit_circuitpython_pca9685 import PCA9685
from paho.mqtt.client import Client as MQTTClient
import serial

class ESP8266:
    def __init__(self, uart_id=0, baudrate=115200, timeout=5):
        try:
            self.uart = UART(uart_id, baudrate=baudrate, tx=14, rx=15, timeout=timeout, loop_control=True, in_buffer_size=1024, out_buffer_size=1024)
        except serial.SerialException as e:
            logging.error(f"Failed to initialize UART: {e}")
            sys.exit(1)

    def _send_command(self, command, delay=1, max_retries=3):
        for _ in range(max_retries):
            self.uart.write(command.encode() + b'\r\n')
            time.sleep(delay)
            response = self._read_response()
            if response in ["OK", "ERROR", "FAIL"]:
                return response
        return None

    def _read_response(self):
        try:
            response = self.uart.read_all()
            if response:
                return response.decode().strip()
            else:
                return None
        except serial.SerialTimeoutException:
            return None

    def test_connection(self):
        return self._send_command("AT\r\n") == "OK"

    def restart(self):
        response = self._send_command("AT+RST\r\n", delay=2)
        if response != "OK":
            logging.error(f"Failed to restart ESP8266: {response}")
        return response == "OK"

    def connect_wifi(self, ssid, password):
        command = f"AT+CWJAP_CUR=\"{ssid}\",\"{password}\"\r\n"
        response = self._send_command(command, delay=5)
        return response == "WIFI GOT IP"

def signal_handler(sig, frame):
    print('Exiting...')
    try:
        esp.uart.close()
    except AttributeError:
        pass
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    logging.basicConfig(level=logging.INFO)

    esp = ESP8266()
    if not esp.test_connection():
        logging.error("Failed to connect to ESP8266")
        sys.exit(1)

    if not esp.restart():
        logging.error("Failed to restart ESP8266")
        sys.exit(1)

    if not esp.connect_wifi("your_ssid", "your_password"):
        logging.error("Failed to connect to Wi-Fi")
        sys.exit(1)

    print("Connected to ESP8266 and Wi-Fi")

