                return response.decode().strip()
            else:
                return None
        except serial.SerialTimeoutException:
            return None

    def test_connection(self):
        return self._send_command("AT\r\n") == "OK"

    def restart(self):
        response = self._send_command("AT+RST\r\n", delay=2)
        if response != "OK":
            logging.error(f"Failed to restart ESP8266: {response}")
        return response == "OK"

    def connect_wifi(self, ssid, password):
        command = f"AT+CWJAP_CUR=\"{ssid}\",\"{password}\"\r\n"
        response = self._send_command(command, delay=5)
        return response == "WIFI GOT IP"

def signal_handler(sig, frame):
    print('Exiting...')
    try:
        esp.uart.close()
    except AttributeError:
        pass
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    logging.basicConfig(level=logging.INFO)

    esp = ESP8266()
    if not esp.test_connection():
        logging.error("Failed to connect to ESP8266")
        sys.exit(1)

    if not esp.restart():
        logging.error("Failed to restart ESP8266")
        sys.exit(1)

    if not esp.connect_wifi("your_ssid", "your_password"):
        logging.error("Failed to connect to Wi-Fi")
        sys.exit(1)

    print("Connected to ESP8266 and Wi-Fi")
```

Note: Replace `"your_ssid"` and `"your_password"` with your actual Wi-Fi network's SSID and password.

