            time.sleep(1)
            response = self.port.readline()
            if response != b"OK\r\n":
                logging.error("Failed to power on GNSS")
                return False
            return True
        except serial.SerialException as e:
            logging.error(f"Failed to power on GNSS: {e}")
            return False

