            longitude = fields[4]
            if longitude == '':
                longitude = None
            else:
                longitude = float(longitude)
            fix_quality = fields[6]
            num_satellites = fields[7]
            return {
                'utc_time': utc_time,
                'latitude': latitude,
                'longitude': longitude,
                'fix_quality': fix_quality,
                'num_satellites': num_satellites
            }
        except (IndexError, ValueError) as e:
            logging.error(f"Failed to parse GGA sentence: {e}")
            return None

    def close(self):
        if self.serial is not None:
            try:
                self.serial.close()
            except Exception as e:
                logging.error(f"Failed to close serial port: {e}")
            self.serial = None

