import threading
import json
import logging
import sys
import signal
import time
import queue
import select
import serial
import picamera2
import picamera2.controls
import adafruit_requests
import paho.mqtt.client as mqtt
from gpiozero import LED
from gpiozero.pins.pigpio import PiGPIOFactory
from flask import Flask, request, jsonify
from flask_cors import CORS
from contextlib import contextmanager

# Set up logging
logging.basicConfig(level=logging.INFO)

# Set up GPIO
factory = PiGPIOFactory()
led = LED(17, pin_factory=factory)

# Set up UART
uart_lock = threading.Lock()
uart = None

@contextmanager
def uart_open():
    global uart
    with uart_lock:
        if uart is None:
            try:
                uart = serial.Serial('/dev/ttyUSB0', 9600, timeout=1, bytesize=serial.EIGHTBITS, parity=serial.PARITY_NONE, stopbits=serial.STOPBITS_ONE)
            except serial.SerialException as e:
                logging.error(f"Failed to open UART: {e}")
                raise
        try:
            yield uart
        finally:
            if uart is not None:
                uart.close()
                uart = None

# Set up web service
app = Flask(__name__)
CORS(app)

# In-memory data store
data_store = []
next_id = 0

def get_next_id():
    global next_id
    next_id += 1
    return next_id - 1

class Item:
    def __init__(self, id, name, done):
        self.id = id
        self.name = name
        self.done = done

    @classmethod
    def from_json(cls, json_data):
        data = json.loads(json_data)
        return cls(data['id'], data['name'], data['done'])

    def to_json(self):
        return json.dumps({'id': self.id, 'name': self.name, 'done': self.done})

def get_item(id):
    for item in data_store:
        if item.id == id:
            return item
    return None

def get_items():
    return data_store

def create_item(name, done):
    if not name or not isinstance(name, str):
        raise ValueError("Invalid name")
    if not isinstance(done, bool):
        raise ValueError("Invalid done")
    item = Item(get_next_id(), name, done)
    data_store.append(item)
    return item

def delete_item(id):
    global data_store
    data_store = [item for item in data_store if item.id != id]

@app.route('/version', methods=['GET'])
def version():
    with uart_open() as uart:
        uart.write(b'*IDN?\n')
        uart.flush()
        response = uart.readline().decode('ascii')
        return response, 200, {'Content-Type': 'text/plain'}

@app.route('/data', methods=['GET'])
def get_data():
    return jsonify([item.to_json() for item in get_items()])

@app.route('/data/<int:item_id>', methods=['GET'])
def get_item_data(item_id):
    item = get_item(item_id)
    if item is None:
        return jsonify({'error': 'Not found'}), 404
    return jsonify(item.to_json())

@app.route('/data', methods=['POST'])
def create_data():
    try:
        data = request.json
        if 'name' not in data or 'done' not in data:
            return jsonify({'error': 'Invalid request'}), 400
        item = create_item(data['name'], data['done'])
        return jsonify(item.to_json()), 201
    except ValueError as e:
        return jsonify({'error': str(e)}), 400

def signal_handler(sig, frame):
    global uart
    if uart is not None:
        uart.close()
    app.shutdown()
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

if __name__ == '__main__':
    try:
        app.run(host='0.0.0.0', port=5000, threaded=True)
    except Exception as e:
        logging.error(f"Failed to start web service: {e}")
        sys.exit(1)

